// Install a built model package without formatting LittleFS or replacing device configuration.
import { readFile } from "node:fs/promises";
import { createHash } from "node:crypto";
import { pathToFileURL } from "node:url";
import { rpc } from "./web/request.js";

const CHUNK_SIZE = 768;
const defaultPackage = new URL("../../build_output/inter-comms-assets/", import.meta.url);

// Validate the complete package before contacting a device or starting an upload.
export async function readAssetPackage(directory = defaultPackage) {
	const manifest = JSON.parse(await readFile(new URL("manifest.json", directory), "utf8"));
	if (!Array.isArray(manifest) || !manifest.length) throw new Error("Invalid model manifest");
	const models = [];
	for (const model of manifest) {
		if (
			!/^\/inter_comms\/model-[0-9a-f]{16}\.webp$/.test(model.path) ||
			!Number.isSafeInteger(model.size) ||
			model.size <= 0 ||
			model.size > 1024 * 1024 ||
			!/^[0-9a-f]{64}$/.test(model.sha256) ||
			!model.path.endsWith(model.sha256.slice(0, 16) + ".webp")
		)
			throw new Error("Invalid model manifest entry");
		const image = await readFile(new URL("." + model.path, directory));
		if (image.length !== model.size || createHash("sha256").update(image).digest("hex") !== model.sha256)
			throw new Error("Model package is damaged: " + model.path);
		models.push({ ...model, image });
	}
	return models;
}

// Check firmware compatibility first, skip installed files, and abort incomplete transfers on failure.
export async function installModels(address, models, { send = rpc, progress = () => {} } = {}) {
	const status = await send(address, { op: "modelStatus" });
	if (!Array.isArray(status.models)) throw new Error("Firmware does not support separate model files");
	for (const model of models) {
		const remote = status.models.find((item) => item.path === model.path);
		if (!remote || remote.sha256 !== model.sha256 || remote.size !== model.size)
			throw new Error("Model package does not match this device; install the matching firmware first");
	}
	for (const model of models) {
		const remote = status.models.find((item) => item.path === model.path);
		if (remote.installed) {
			progress(model, "already installed");
			continue;
		}
		let started = false;
		try {
			const begin = await send(address, { op: "modelBegin", body: { path: model.path } });
			if (!begin.installed) {
				started = true;
				for (let offset = 0; offset < model.image.length; offset += CHUNK_SIZE) {
					await send(address, {
						op: "modelChunk",
						body: {
							path: model.path,
							offset,
							data: model.image.subarray(offset, offset + CHUNK_SIZE).toString("hex"),
						},
					});
				}
				await send(address, { op: "modelFinish", body: { path: model.path } });
				started = false;
			}
			progress(model, "installed");
		} catch (error) {
			if (started) {
				try {
					await send(address, { op: "modelAbort", body: { path: model.path } });
				} catch {}
			}
			throw error;
		}
	}
}

// Explicit addresses keep installation scoped to the devices selected by the operator.
async function main(addresses) {
	if (!addresses.length)
		throw new Error(
			"Usage: node usermods/inter_comms_ui/upload_models.mjs http://DEVICE_IP [http://OTHER_DEVICE_IP ...]",
		);
	const models = await readAssetPackage();
	for (const address of addresses) {
		const url = new URL(address);
		if (!["http:", "https:"].includes(url.protocol) || url.username || url.password)
			throw new Error("Use an HTTP device address without credentials");
		console.log("Installing model files on " + url.origin);
		await installModels(url.origin, models, {
			progress: (model, state) => console.log("  " + model.file + ": " + state),
		});
	}
}
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
	main(process.argv.slice(2)).catch((error) => {
		console.error(error.message);
		process.exitCode = 1;
	});
}
